  "confidence": 0.99,
  "anomalies": [
    {
      "category": "open_connection",
      "components": ["REG3", "FCC2", "NAVC2"],
      "pins": ["REG3.1", "FCC2.11", "FCC2.27", "FCC2.50", "FCC2.75", "FCC2.100", "NAVC2.19", "NAVC2.32", "NAVC2.48", "NAVC2.64"],
      "nets": ["+3.3V", "+3V3", "unconnected-(FCC2-VDD-Pad11)", "unconnected-(FCC2-VDD-Pad27)", "unconnected-(FCC2-VDD-Pad50)", "unconnected-(FCC2-VDD-Pad75)", "unconnected-(FCC2-VDD-Pad100)", "unconnected-(NAVC2-VDD-Pad19)", "unconnected-(NAVC2-VDD-Pad32)", "unconnected-(NAVC2-VDD-Pad48)", "unconnected-(NAVC2-VDD-Pad64)"],
      "observed": "REG3 output is on +3.3V, while decoupling capacitors are on a separate +3V3 net. The netlist lists all VDD pins of both MCUs as unconnected rather than on either rail; +3V3 has no regulator output connected to it.",
      "expected": "The specification says the 3.3 V rail feeds both MCUs and sensors. The regulator output and MCU VDD pins should therefore be connected to the intended 3.3 V supply.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (name \"+3.3V\") ... (node (ref \"REG3\") (pin \"1\") (pinfunction \"OUT\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"+3V3\") ... (node (ref \"NAVC2\") (pin \"1\") (pinfunction \"VBAT\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"unconnected-(FCC2-VDD-Pad11)\") (node (ref \"FCC2\") (pin \"11\") (pinfunction \"VDD\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"unconnected-(NAVC2-VDD-Pad19)\") (node (ref \"NAVC2\") (pin \"19\") (pinfunction \"VDD\"))"
        },
        {
          "source": "spec",
          "quote": "3.3 V feeds both MCUs (FCC, NAVC) and all I2C sensor ICs"
        }
      ],
      "impact": "As netlisted, neither MCU receives power at its VDD pins, so the flight-control and navigation computers cannot operate. The separate +3V3 net also lacks a connection to the regulator output.",
      "confidence": 0.99
    },
    {
      "category": "bridged_nets",
      "components": ["FCC2", "UART3_FCC2"],
      "pins": ["FCC2.48", "FCC2.73", "UART3_FCC2.3", "UART3_FCC2.4"],
      "nets": ["NET0042", "NET0141"],
      "observed": "Both FCC MCU VCAP pins are connected directly to pins on the UART3 connector; the netlist shows no VCAP capacitor on either net.",
      "expected": "STM32H753 VCAP pins should have their required local capacitors to ground, not be routed as UART connector signals.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (name \"NET0042\") (node (ref \"FCC2\") (pin \"48\") (pinfunction \"VCAP\")) (node (ref \"UART3_FCC2\") (pin \"3\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"NET0141\") (node (ref \"FCC2\") (pin \"73\") (pinfunction \"VCAP\")) (node (ref \"UART3_FCC2\") (pin \"4\")))"
        },
        {
          "source": "netlist",
          "quote": "(pin (num \"48\") (name \"VCAP\") (type \"power_out\"))"
        }
      ],
      "impact": "The MCU's internal regulator may not operate correctly without the required VCAP capacitors, preventing reliable startup or operation. The connector also exposes these internal-regulator nodes instead of the intended UART signals.",
      "confidence": 0.98
    }
  ],
  "summary": "Anomalies are present: the MCU supply pins are unconnected, and the regulator output is on a different net from the MCU-side +3V3 rail. In addition, both FCC VCAP pins are routed to the UART3 connector rather than receiving the required capacitor connections."
}

